function findElTagList(source) {
  const tagReg = /<el-(.*?)[\s|>]/g;
  const arr = source.matchAll(tagReg);
  const tagSet = new Set();
  for(let tag of arr) {
    const tagName = tag[1];
    if(!tagSet.has(tagName)) {
      tagSet.add(tagName)
    }
  };
  return Array.from(tagSet)
}

function upperCaseByIndex(string, index) {
  if(Object.prototype.toString.call(index).slice(8,-1) === 'Array') {
    if(index.length === 0) {
      return
    }
    const partList = [];
    let pointer = 0;
    // Why use a counter here, because I don't want to write ugly index [i]
    let counter = 0;
    for(let i of index) {
      partList.push(string.slice(pointer, i));
      partList.push(string.slice(i, i+1).toUpperCase());
      pointer = i+1;
      counter++;
      if(counter === index.length) {
        partList.push(string.slice(pointer));
      }
    };
    return partList.join('')
  }else {
    const headPart = string.slice(0, index)
    let upperPart = string.slice(index, index+1).toUpperCase();
    const endPart = string.slice(index+1);
    return headPart+upperPart+endPart
  }
}

function getImportNameList(tagList) {
  const importNameList = [];
  for(let tag of tagList) {
    if(tag.indexOf('-') !== -1) {
      const indexList = [0];
      const reg = /-/g;
      const matchList = tag.matchAll(reg);
      tag = tag.replace(reg, '');
      for(let regInfo of matchList) {
        indexList.push(regInfo.index);
      };
      importNameList.push(upperCaseByIndex(tag, indexList))
    }else {
      importNameList.push(upperCaseByIndex(tag, 0))
    }
  };
  return importNameList
}

function replaceComponents(importNameList, source) {
  let handledSource = source;
  const componentsList = [];
  const componentsReg = /components\s*:[\s\S]*?}/g;
  const defaultReg = /export\s*default\s*{/g
  const componentsPart = handledSource.match(componentsReg);
  for(let tag of importNameList) {
    if(!componentsPart || componentsPart[0].indexOf(tag) === -1) {
      componentsList.push(`[${tag}.name]: ${tag}`)
    };
  };
  if(componentsList.length) {
    const componentStr = `components: {${componentsList.join(',')},`
    if(componentsReg.test(handledSource)) {
      handledSource = handledSource.replace(/components:\s*?{/g, componentStr);
    }else {
      handledSource = handledSource.replace(defaultReg, 
        `export default {
          ${componentStr}
        },
        `
      );
    }
  }
  return handledSource
}

function replaceImport(importNameList, source) {
  let handledSource = source;
  const importReg = /import\s*{[\s\S]*?from.*["|']element-ui["|']/g;
  const scriptReg = /<script>/g;
  const importStr = `import{${importNameList.join(',')}} from 'element-ui'`
  if(importReg.test(handledSource)) {
    handledSource = handledSource.replace(importReg, importStr);
  }else {
    handledSource = handledSource.replace(scriptReg, 
      `<script>
        ${importStr}
      `
    );
  }
  return handledSource;
}


module.exports = function(source) {
  let handledSource = source;
  const tagList = findElTagList(handledSource);
  if(tagList.length) {
    const importNameList = getImportNameList(tagList);
    handledSource = replaceImport(importNameList, handledSource);
    handledSource = replaceComponents(importNameList, handledSource)
  };
  return handledSource
}